def transform(grid):
    # Color the interior of closed rectangular outlines with a contrasting color.
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    line=next(v for v in set(sum(g,[])) if sum(row.count(v) for row in g)<h*w)
    fill=next(v for v in set(sum(g,[])) if v!=line)
    # Interior cells bounded by line on all four sides: flood regions, fill enclosed background components.
    seen=set()
    for r in range(h):
      for c in range(w):
       if g[r][c]!=fill or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); comp=[]; outside=False
       while stack:
        y,x=stack.pop(); comp.append((y,x))
        if y==0 or x==0 or y==h-1 or x==w-1: outside=True
        for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
         if 0<=yy<h and 0<=xx<w and g[yy][xx]==fill and (yy,xx) not in seen:
          seen.add((yy,xx)); stack.append((yy,xx))
       if not outside:
        for y,x in comp: g[y][x]=4 if line==2 else 4
    return g
